-- ----------------------------
-- Table structure for property
-- ----------------------------
DROP TABLE IF EXISTS `property`;
CREATE TABLE `property`  (
  `property_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '房产唯一标识',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '业主ID',
  `type_id` int(11) NOT NULL COMMENT '类型ID',
  `building_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '楼栋号（如1栋/A栋）',
  `room_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间号（如101/202B）',
  `floor_area` decimal(8, 2) NOT NULL COMMENT '建筑面积（单位：平方米）',
  `status` enum('occupied','vacant') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'occupied' COMMENT '使用状态',
  `floor_plan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '户型图存储路径',
  `purchase_date` date NULL DEFAULT NULL COMMENT '购置日期',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`property_id`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE,
  INDEX `idx_property_location`(`building_number`, `room_number`) USING BTREE,
  INDEX `property_ibfk_2`(`type_id`) USING BTREE,
  CONSTRAINT `property_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `property_ibfk_2` FOREIGN KEY (`type_id`) REFERENCES `types` (`tid`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

