  `status` enum('pending','processing','completed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'pending' COMMENT '处理状态',
  `handler_id` int(11) NULL DEFAULT NULL COMMENT '处理人ID',
  `handle_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '处理结果',
  `submit_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `completion_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`repair_id`) USING BTREE,
  INDEX `handler_id`(`handler_id`) USING BTREE,
  INDEX `idx_repair_user`(`user_id`) USING BTREE,
  INDEX `idx_completion_time`(`completion_time`) USING BTREE,
  INDEX `repair_ibfk_3`(`type_id`) USING BTREE,
  CONSTRAINT `repair_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `repair_ibfk_2` FOREIGN KEY (`handler_id`) REFERENCES `user` (`user_id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `repair_ibfk_3` FOREIGN KEY (`type_id`) REFERENCES `types` (`tid`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

