INSERT INTO `system_log` VALUES (8745, 'GET', '{\"ARGS\":\"[]\",\"CLASS_METHOD\":\"com.example.controller.RepairController.all\",\"URL\":\"http://localhost:8080/api/repair/all\",\"SPEND_TIME\":54,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"repairId\":2,\"userId\":55,\"typeId\":15,\"submitterName\":\"雷欧斯\",\"fullAddress\":\"4栋405室\",\"description\":\"esgsegfaefa\",\"handleResult\":\"请勿乱用报修功能，希望您能理解\",\"type\":\"电力维修\",\"handlerId\":1,\"handlerName\":\"admin\",\"statusDesc\":\"已解决\",\"submitTime\":\"2025-02-20 15:45:14\",\"completionTime\":\"2025-03-16 16:01:43\"},{\"repairId\":3,\"userId\":56,\"typeId\":15,\"submitterName\":\"白丽萍\",\"fullAddress\":\"2栋304室\",\"description\":\"afqqgqgqgq\",\"handleResult\":\"good\",\"type\":\"电力维修\",\"handlerId\":1,\"handlerName\":\"admin\",\"statusDesc\":\"已解决\",\"submitTime\":\"2025-02-20 15:45:23\",\"completionTime\":\"2025-02-20 15:46:06\"},{\"repairId\":4,\"userId\":58,\"typeId\":15,\"submitterName\":\"王浩\",\"fullAddress\":\"3栋204室\",\"description\":\"aefsefaefae\",\"handleResult\":\"3c223cc3\",\"type\":\"电力维修\",\"handlerId\":53,\"handlerName\":\"蓝染\",\"statusDesc\":\"已解决\",\"submitTime\":\"2025-02-20 15:49:41\",\"completionTime\":\"2025-03-18 14:57:26\"},{\"repairId\":6,\"userId\":56,\"typeId\":19,\"submitterName\":\"白丽萍\",\"fullAddress\":\"2栋304室\",\"description\":\"我家空调坏了，请求修理\",\"handleResult\":\"空调已经安排工作人员去解决了，祝您生活愉快！\",\"type\":\"室内维修\",\"handlerId\":54,\"handlerName\":\"林可\",\"statusDesc\":\"已解决\",\"submitTime\":\"2025-03-07 14:26:55\",\"completionTime\":\"2025-03-14 15:59:01\"},{\"repairId\":7,\"userId\":60,\"typeId\":18,\"submitterName\":\"吴一鸣\",\"fullAddress\":\"2栋104室\",\"description\":\"西门的门禁坏了还几天了，都没人来修一下，怎么保证我们业主的安全？\",\"handleResult\":\"非常抱歉给您带来困扰，现已解决问题，感谢您的支持\",\"type\":\"设备维修\",\"handlerId\":53,\"handlerName\":\"蓝染\",\"statusDesc\":\"已解决\",\"submitTime\":\"2025-03-14 15:54:39\",\"completionTime\":\"2025-03-18 14:58:34\"},{\"repairId\":8,\"userId\":58,\"typeId\":15,\"submitterName\":\"王浩\",\"ful