INSERT INTO `system_log` VALUES (8767, 'GET', '{\"ARGS\":\"[20]\",\"CLASS_METHOD\":\"com.example.controller.RepairController.get\",\"URL\":\"http://localhost:8080/api/repair/rid/20\",\"SPEND_TIME\":4,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":{\"repairId\":20,\"userId\":1,\"typeId\":15,\"submitterName\":\"admin\",\"fullAddress\":null,\"description\":\"111\",\"handleResult\":null,\"type\":\"电力维修\",\"handlerId\":1,\"handlerName\":\"admin\",\"statusDesc\":\"处理中\",\"submitTime\":\"2025-05-21 16:53:50\",\"completionTime\":\"2025-05-21 16:56:21\"}}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-21 16:57:42');
