INSERT INTO `system_log` VALUES (8770, 'GET', '{\"ARGS\":\"[repair]\",\"CLASS_METHOD\":\"com.example.controller.TypeController.allActive\",\"URL\":\"http://localhost:8080/api/type/all-active/repair\",\"SPEND_TIME\":5,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"tid\":15,\"type\":\"repair\",\"description\":\"电力维修\",\"status\":\"active\"},{\"tid\":16,\"type\":\"repair\",\"description\":\"水管维修\",\"status\":\"active\"},{\"tid\":17,\"type\":\"repair\",\"description\":\"电梯维修\",\"status\":\"active\"},{\"tid\":18,\"type\":\"repair\",\"description\":\"设备维修\",\"status\":\"active\"},{\"tid\":19,\"type\":\"repair\",\"description\":\"室内维修\",\"status\":\"active\"}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-21 16:57:47');
