INSERT INTO `system_log` VALUES (8796, 'GET', '{\"ARGS\":\"[81, 物业费, null]\",\"CLASS_METHOD\":\"com.example.controller.PaymentController.getByReq\",\"URL\":\"http://localhost:8080/api/payment/req\",\"SPEND_TIME\":0,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"payId\":126,\"userId\":81,\"propertyId\":18,\"formattedAmount\":\"45.30￥\",\"username\":\"Gibson\",\"fullAddress\":\"3栋801室\",\"type\":\"物业费\",\"statusDesc\":\"未支付\",\"operatorId\":1,\"operatorName\":\"admin\",\"generateTime\":\"2025-05-19 15:41:14\",\"paymentTime\":null}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-21 17:00:52');
