INSERT INTO `system_log` VALUES (8856, 'GET', '{\"ARGS\":\"[property]\",\"CLASS_METHOD\":\"com.example.controller.TypeController.allActive\",\"URL\":\"http://localhost:8080/api/type/all-active/property\",\"SPEND_TIME\":4,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"tid\":7,\"type\":\"property\",\"description\":\"住宅\",\"status\":\"active\"},{\"tid\":9,\"type\":\"property\",\"description\":\"商品房\",\"status\":\"active\"}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:20:39');
