\":77,\"username\":null,\"realName\":\"奈特\",\"phone\":null,\"roleName\":null,\"position\":null,\"gender\":null,\"address\":null,\"status\":null,\"createdAt\":null,\"hireDate\":null},{\"userId\":81,\"username\":null,\"realName\":\"Gibson\",\"phone\":null,\"roleName\":null,\"position\":null,\"gender\":null,\"address\":null,\"status\":null,\"createdAt\":null,\"hireDate\":null},{\"userId\":83,\"username\":null,\"realName\":\"童一名\",\"phone\":null,\"roleName\":null,\"position\":null,\"gender\":null,\"address\":null,\"status\":null,\"createdAt\":null,\"hireDate\":null}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:20:39');
INSERT INTO `system_log` VALUES (8858, 'GET', '{\"ARGS\":\"[]\",\"CLASS_METHOD\":\"com.example.controller.AnnounceController.all\",\"URL\":\"http://localhost:8080/api/announce/all\",\"SPEND_TIME\":13,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"aid\":1,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"小区关于办理业主卡的通知\",\"content\":\"<p style=\\\"text-align: left;\\\">尊敬的住户:<br><br>你们好!现本小区已进入装修阶段,进出苑区人员日益增多,管理处为加强小区人员进出管理,确保苑区的安全和谐,须对苑区住户办理业主卡,住户须凭业主卡进出苑区。请业主于近期内到管理处办理,谢谢合作!</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-02-19 13:54:26\"},{\"aid\":3,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"111\",\"content\":\"<p>11111</p>\",\"statusDesc\":\"已删除\",\"publishTime\":\"2025-02-19 14:02:57\"},{\"aid\":4,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"物业冬季消防安全的温馨提示\",\"content\":\"<p style=\\\"text-align: left;\\\">物业冬季消防安全的温馨提示<br><br>　　尊敬的业主：<br><br>　　秋冬季节气候干燥，为火灾多发季节，为了提高全体业主防火、灭火及火灾自救能力，物业服务中心对日常家居防火、灭火等安全常识温馨提示如下：<br><br>　　1、插座上不要使用过多的用电设备。<br><br>　　2、离家或入睡前，应对用电器具、燃气开关及遗留火种进行检查，用电设备长期不使用时，应切断电源或拔下插头。<br><br>　　3、物业管理小助手：不可随意将烟蒂、火柴杆扔在废纸篓内或者可燃杂物上，不要躺在床上或沙发上吸烟，尤其是酒后或过度疲劳时;不要把烟头随手从窗口、阳台扔出、以防掉到楼下可燃物上引起火灾;不可用纸盒等可燃物当作烟灰缸，也不可将尚有火种的烟灰倒入废纸篓内。<br><br>　　4、点燃的蚊香不要靠蚊帐、窗帘等可燃物，以防风吹或碰撞引燃可燃物引起火灾。切忌把点燃的蚊香直接放在纸箱、木桌等可燃物上。人离开房间时应将蚊香、香烛熄灭。<br><br>　　5、家中不可存放超过0.5公升的汽油、酒精、香蕉水等易燃易爆物品。<br><br>　　6、教育儿童不玩火、不随意摆弄电器设备，家长外出时不能将孩子独自留在家中或反锁在室内，应托人照看。<br><br>　　7、切勿在走廊、楼梯口等处堆放杂物，要保证通道和安全出口的畅通。<br><br>　　8、不在禁放区及楼道、阳台等处燃放烟花爆竹。<br><br>　　9、禁止洗衣机一次投入衣物过多，使电机过载，导致线圈过热而发生短路起火。应尽量使用低泡洗衣粉，以免洗涤时起泡外溢，降低绝缘性能，引起短路和击穿。<br><br>　　10、必须保证电冰箱后部保持干燥、通风，切勿在电冰箱后面堆放可燃物;防止电冰箱电源线与压缩机、冷凝器接触，以防电线绝缘层老化，引起漏电，导致火灾。<br><br>　　11、使用电熨斗切勿长时间通电，不论是暂时离开或停止使用都要先切断电源，将电熨斗放置在专用的架上;<br><br>　　12、家用电器或电气线路起火，首先要切断电源，再用灭火器或水灭火，不可带电直接泼水灭火，以防触电或电器爆炸伤人。<br><br>　　13、油锅起火不能用水扑救，应先关闭炉灶阀门，然后盖上锅盖或用大块湿抹布覆盖，令火窒息，还可向锅内放入切好的蔬菜，冷却灭火。<br><br>　　14、物业管理小助手：煤气泄漏要迅速关闭气阀，开窗通风，切勿触动电器开关和使用明火，并迅速通知专业维修部门来处理。切记不要在燃气泄漏场所拨打电话。<br><br>　　15、建议家中配备家用灭火器，以备紧急情况下使用。<br><br>　　如您需要更详尽地了解有关消防安全知识或消防器材的使用方法，也可直接与物业服务中心电话沟通或要求进行上门指导，我们将委派有经验的工作人员为您服务。</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:19:47\"},{\"aid\":5,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"物业关于爱护公共设施温馨提示\",\"content\":\"<p style=\\\"text-align: left;\\\">　物业关于爱护公共设施温馨提示<br><br>　　爱护公共设施 人人有责<br><br>　　小区最近发生了什么?<br><br>　　近日，发现小区内出现了“受伤”的消防器材，“毁容”的电梯标识，“破烂”的公告牌，“苦不堪言”的游乐设施，这些原本能为我们带来幸福生活的公共设施也影响了小区业主们的正常生活，让整洁漂亮的小区受到了污染。<br><br>　　小区内所有的公共设施、设备都是为业主服务的，可是它们也需要业主们的维护爱惜。小区内的每一件公共设备，因为一个人或多个人长期的不当使用或人为破坏而无法使用，这着实让人感到遗憾和痛心，也会对其他业主造成不便。<br><br>　　小区内的公共服务设施有哪些呢?<br><br>　　1、绿化及小品(如亭台楼阁、水池喷泉、公共座椅等)<br><br>　　2、公共照明设备<br><br>　　3、公共消防设备、消防楼梯、通道<br><br>　　4、公共安全设备(如围墙、摄像头、护栏、小区大门、栏杆等)<br><br>　　5、公共场地及公共道路<br><br>　　6、公共给排水设施(如下水渠道、管井、各类水泵、管道阀门、雨水管等)<br><br>　　7、公共配电设施(如配电箱、配电柜、电力管井、电闸箱、表具、线槽等)<br><br>　　8、公共弱电设施(如电信设备、网络光纤设备、弱电管井等)<br><br>　　9、公共健身及儿童娱乐设施<br><br>　　10、建筑物楼顶屋面及共用的外墙<br><br>　　11、电梯、电梯等候厅<br><br>　　12、公共楼道、楼梯、单元门厅、共用的楼宇大堂、公共卫生间<br><br>　　13、建筑物的地基等基础设施<br><br>　　案例链接<br><br>　　青岛一综合执法人员在巡查至天水路一小区时，发现一处面积将近10余平方米的绿地被擅自毁坏。<br><br>　　经了解，执法人员发现小区居民陶某趁春种时节，把小区公共绿地占为私有，变成自家的菜园子，准备种植蔬菜。执法人员在现场看到，业主为了种菜，将一处绿地原有的草皮全部铲除，仅剩光秃秃的黄土，面积达10余平方米。<br><br>　　随意圈占、毁绿种菜的行为，不仅破坏公共环境，更侵犯其他住户的公共权利。<br><br>　　依据《青岛市城市绿化条例》第三十四条中的规定，执法人员责令当事人限期整改，将此处恢复原状，造成的损失依法承担责任，立案处罚200元。<br><br>　　一起来看看<br><br>　　随意破坏小区内的公共服务设施<br><br>　　会造成什么后果?<br><br>　　1、故意毁坏公私财物行为，达到数额较大或有其他严重情节的将构成犯罪。<br><br>　　2、所谓情节严重，是指毁坏重要物品损失严重的，毁坏手段特别恶劣的;毁坏急需物品引起严重后果的;动机卑鄙企图嫁祸于人的，等等。<br><br>　　3、故意毁坏公私财物，情节较轻的，是一般违反治安管理行为，应按照《治安管理处罚法》第23条规定，处15日以下拘留或者警告，可以单处或者并处二百元以下罚款。<br><br>　　同时按该条例第8条规定，责令行为人赔偿损失。犯罪主体是一般主体。已满16岁的人犯本罪，应当负刑事责任。<br><br>　　4、如果损失较大，会构成故意毁坏公私财物罪，追究刑事责任。根据《最高检、公安部关于公安机关管辖的刑事案件立案追诉标准的规定》第三十三条 [故意毁坏财物案(刑法第二百七十五条)]故意毁坏公私财物，数额较大或者有其他严重情节的，处三年以下有期徒刑、拘役或者罚金;数额巨大或者有其他特别严重情节的，处三年以上七年以下有期徒刑。<br><br>　　涉嫌下列情形之一的，应予立案追诉：<br><br>　　(一)造成公私财物损失五千元以上的;<br><br>　　(二)毁坏公私财物三次以上的;<br><br>　　(三)纠集三人以上公然毁坏公私财物的;<br><br>　　(四)其他情节严重的情形。<br><br>　　如果该业主三次以上破坏公共设施可以对其进行起诉，由法院来裁定和处置他，或者要求他赔偿。<br><br>　　爱护公物倡议书<br><br>　　在此，物业服务处向全体业主发出倡议：<br><br>　　1、请小朋友不要在小区绿化带内追逐打闹，请爱护小区花草树木，不任意践踏草坪，不攀折花木。<br><br>　　2、请爱护小区内桌椅、灯具、围栏等公共设施，不乱涂乱刻，不随意粘贴物品，不乱踢打。<br><br>　　3、请叮嘱孩子远离园区危险地带，如配电箱、水系周边地区玩耍，以免发生意外。<br><br>　　4、请不要随意使用室内外消火栓、消防喷淋、紧急呼叫按钮等应急设备设施。<br><br>　　5、发现不文明行为，请您大胆制止，维护全体业主的公共利益。<br><br>　　勿以善小而不为，勿以恶小而为之。亲爱的业主们，让我们携起手来，杜绝损坏公物的行为。爱护公物，从我做起，从小事做起，从身边做起，让美丽的小区在我们的精心呵护下变得更加和谐，更加舒适宜人!</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:20:23\"},{\"aid\":6,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"物业公众号服务迁移的通知\",\"content\":\"<p style=\\\"text-align: left;\\\">关于物业公众号服务迁移的通知<br><br>　　尊敬的业主：<br><br>　　本公众号已更名为“南国丽城物业服务信息”，2019年11月1日起本公众号将停止所有服务。缴费、留言、报修、投诉建议等将全部迁移至新公众号“南国丽城物业服务中心”(微信号：XXXXX)。<br><br>　　请业主于2019年11月1日前关注新公众号，并在个人中心完成业主信息认证，以便及时接收物业信息、缴费通知，和使用各项功能，如：费用查询、费用缴纳、报修、投诉建议等。<br><br>　　嘉润物业将不断提高服务水平，为业主提供更优质、更便捷、更高效的物业服务。<br><br>　　新公众号(南国丽城物业服务中心)<br><br>　　二维码：(略)<br><br>　　罗定市嘉润物业服务有限公司<br><br>　　南国丽城物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:21:04\"},{\"aid\":7,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"小区空调外机安全加固温馨提示\",\"content\":\"<p style=\\\"text-align: left;\\\">最近经物业人员巡查发现，<br><br>　　有个别业主家安装的空调外挂机不规范，存在诸多安全隐患。为了不影响您的正常生活，避免给您和他人带来不必要的损失，<br><br>　　请各位业主注意以下事项提示：<br><br>　　小区空调外机安全加固温馨提示<br><br>　　尊敬的业主：<br><br>　　您好!<br><br>　　近年来，由于常年风吹雨淋，小区部分空调室外机支架已出现松动、腐蚀等现象。空调室外机支架损坏导致维修工、室外机坠落的现象屡有发生，对行人及住户造成很大的安全隐患。请业主尽快做好以下几点防护措施，以保证自身和他人安全：<br><br>　　一、全体业主有安装空调外机的，检查空调外机支架是否存在歪斜、安装不牢固以及严重锈蚀等安全隐患。若发现安全隐患，请第一时间联系空调厂家进行安全检查以及加强外机的加固工作，防止因大风天气导致空调脱落，做到空调外机安装牢靠。<br><br>　　二、请勿将空调外机安装在除预留位置以外任何区域。严禁超出预留位置护栏安装。<br><br>　　三、及时检查空调室外机百叶窗、支架、护栏是否锈蚀、未关闭牢靠、松动、脱落等隐患，发现请及时维护或更换。<br><br>　　四、空调冷却水应引入室内或空调落水管排放，不得直接向沿建筑墙面和地面排放，不然使用空调时排水管长期滴水，日积月累会使墙面受损、腐蚀，同时滴答滴答的水声也会造成邻里不和谐。<br><br>　　五、不要在空调室外机、窗台上和窗户、阳台外等处搁置或悬挂物品。<br><br>　　六、检查空调主机排水软管是否有松脱、扭曲、压扁、破裂漏水，及时维护。<br><br>　　七、检查空调主机运行是否发出较大噪音，如有问题敬请业户联系专业空调维修单位进行维修保养。<br><br>　　八、空调外机及支架属产权人(业主)的自用部分，产权人(业主)有维护它的安全状态的义务和安全维护责任。<br><br>　　小区的平安、和谐，靠大家共同努力维护。感谢全体业主对小区的平安工作给予的积极支持和配合!<br><br>　　物业服务中心<br><br>　　2023年7月1日</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:21:44\"},{\"aid\":8,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"关于失物领取相关公告\",\"content\":\"<p style=\\\"text-align: left;\\\">亲爱的业主：</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp;最近有不少业主在小区内拾取到无人认领的失物，其中包括水杯，笔，雨伞等物品，请丢失相关物品的失主尽快到物业中心前台认领失物，也再次提醒各位业主注意随身物品，避免再次丢失导致个人利益损失，祝各位业主生活愉快！</p><p><br></p><p style=\\\"text-align: right;\\\">2025.3.14</p><p style=\\\"text-align: right;\\\">物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-14 15:46:36\"},{\"aid\":9,\"publisherId\":57,\"publisherName\":\"杨平\",\"title\":\"4月到来，物业服务再升级！\",\"content\":\"<p style=\\\"text-align: left;\\\">亲爱的业主：</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp;您好！</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp; 在新的一个月的到来之际，我们物业工作也迎来了新的一轮升级，我们永远遵循“全心全意为业主服务”的最高宗旨，全面提升我们的物业服务能力，在生机勃勃的4月份，我们为业主带来了各种有趣的活动，增进小区的和谐氛围，提高业主的幸福度，敬请期待！</p><p style=\\\"text-align: right;\\\">2025.4.1</p><p style=\\\"text-align: right;\\\">物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-04-01 15:23:50\"},{\"aid\":10,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"test\",\"content\":\"<p><br></p>\",\"statusDesc\":\"已删除\",\"publishTime\":\"2025-04-17 11:42:37\"}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:20:41');
