INSERT INTO `system_log` VALUES (8868, 'GET', '{\"ARGS\":\"[]\",\"CLASS_METHOD\":\"com.example.controller.ComplaintController.all\",\"URL\":\"http://localhost:8080/api/complaint/all\",\"SPEND_TIME\":67,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"cid\":1,\"userId\":54,\"typeId\":14,\"submitterName\":\"林可\",\"fullAddress\":null,\"content\":\"1111\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":\"双方交涉友好\",\"submitTime\":\"2025-02-19 15:45:46\",\"handleTime\":\"2025-02-19 16:58:14\"},{\"cid\":2,\"userId\":56,\"typeId\":14,\"submitterName\":\"白丽萍\",\"fullAddress\":\"2栋304室\",\"content\":\"2222222\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":\"222222\",\"submitTime\":\"2025-02-19 16:53:13\",\"handleTime\":\"2025-03-17 16:39:07\"},{\"cid\":6,\"userId\":54,\"typeId\":14,\"submitterName\":\"林可\",\"fullAddress\":null,\"content\":\"2栋楼下在晚上8点以后有噪音，请查明并解决\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":54,\"handlerName\":\"林可\",\"handleResult\":\"已加强管制，请业主放心\",\"submitTime\":\"2025-03-06 18:11:04\",\"handleTime\":\"2025-03-17 16:51:34\"},{\"cid\":7,\"userId\":58,\"typeId\":14,\"submitterName\":\"王浩\",\"fullAddress\":\"3栋204室\",\"content\":\"最近晚上邻居很吵，处理一下\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":\"已与住户友好沟通解决\",\"submitTime\":\"2025-03-10 17:42:29\",\"handleTime\":\"2025-03-12 17:34:21\"},{\"cid\":8,\"userId\":60,\"typeId\":11,\"submitterName\":\"吴一鸣\",\"fullAddress\":\"2栋104室\",\"content\":\"2栋一楼的垃圾3天都没人清理，怎么回事？\",\"statusDesc\":\"已解决\",\"type\":\"服务质量\",\"handlerId\":54,\"handlerName\":\"林可\",\"handleResult\":\"亲爱的业主非常抱歉，我们已经安排了新的保洁人员，加强相关的培训\",\"submitTime\":\"2025-03-14 15:51:52\",\"handleTime\":\"2025-03-14 15:57:42\"},{\"cid\":9,\"userId\":60,\"typeId\":13,\"submitterName\":\"吴一鸣\",\"fullAddress\":\"2栋104室\",\"content\":\"200的物业费，有没有搞错，我才住几个月，我住的上个小区都没这么贵！\",\"statusDesc\":\"已解决\",\"type\":\"物业费用\",\"handlerId\":72,\"handlerName\":\"曾梓萌\",\"handleResult\":\"\'and updatexml(1,concat(0x7e,(select @@version)),1) or \'1\'=\'1\",\"submitTime\":\"2025-03-14 15:53:39\",\"handleTime\":\"2025-03-20 16:52:11\"},{\"cid\":11,\"userId\":55,\"typeId\":14,\"submitterName\":\"雷欧斯\",\"fullAddress\":\"4栋405室\",\"content\":\"1111\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":\"111\",\"submitTime\":\"2025-03-14 17:01:35\",\"handleTime\":\"2025-03-14 17:01:58\"},{\"cid\":12,\"userId\":60,\"typeId\":14,\"submitterName\":\"吴一鸣\",\"fullAddress\":\"2栋104室\",\"content\":\"是的1\",\"statusDesc\":\"已解决\",\"type\":\"其它\",\"handlerId\":72,\"handlerName\":\"曾梓萌\",\"handleResult\":\"<Img src = x onerror = \\\"javascript: window.onerror = alert; throw XSS\\\">\",\"submitTime\":\"2025-03-20 14:00:25\",\"handleTime\":\"2025-03-20 16:52:24\"},{\"cid\":13,\"userId\":64,\"typeId\":10,\"submitterName\":\"寿屋及\",\"fullAddress\":\"3栋701室\",\"content\":\"你们的前台态度不是很友善啊，每次去办点事都不会说什么好话\",\"statusDesc\":\"已解决\",\"type\":\"服务态度\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":\"已加强相关物业人员的素质培训\",\"submitTime\":\"2025-03-24 14:26:28\",\"handleTime\":\"2025-03-24 14:48:11\"},{\"cid\":14,\"userId\":64,\"typeId\":11,\"submitterName\":\"寿屋及\",\"fullAddress\":\"3栋701室\",\"content\":\"最近怎么老是有推销的人上来敲我门，打扰到我了，你们这么放心让这些人进来吗\",\"statusDesc\":\"已解决\",\"type\":\"服务质量\",\"handlerId\":59,\"handlerName\":\"王保林\",\"handleResult\":\"ok\",\"submitTime\":\"2025-03-24 14:28:14\",\"handleTime\":\"2025-03-24 14:44:52\"},{\"cid\":15,\"userId\":1,\"typeId\":14,\"submitterName\":\"admin\",\"fullAddress\":null,\"content\":\"test\",\"statusDesc\":\"受理中\",\"type\":\"其它\",\"handlerId\":1,\"handlerName\":\"admin\",\"handleResult\":null,\"submitTime\":\"2025-03-25 14:05:10\",\"handleTime\":\"2025-04-17 11:44:18\"},{\"cid\":16,\"userId\":73,\"typeId\":14,\"submitterName\":\"陆吾\",\"fullAddress\":\"8栋206室\",\"content\":\"2栋楼下在晚上8点以后有噪音，请查明并解决\",\"statusDesc\":\"已解决\",