INSERT INTO `system_log` VALUES (8895, 'GET', '{\"ARGS\":\"[]\",\"CLASS_METHOD\":\"com.example.controller.StaticController.getHomeData\",\"URL\":\"http://localhost:8080/api/static/getHomeData\",\"SPEND_TIME\":17,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":{\"userCount\":14,\"lastMonthUserCount\":4,\"emptyPropertyCount\":6,\"lastMonthEmptyPropertyCount\":6,\"announcements\":[{\"aid\":9,\"publisherId\":57,\"publisherName\":\"杨平\",\"title\":\"4月到来，物业服务再升级！\",\"content\":\"<p style=\\\"text-align: left;\\\">亲爱的业主：</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp;您好！</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp; 在新的一个月的到来之际，我们物业工作也迎来了新的一轮升级，我们永远遵循“全心全意为业主服务”的最高宗旨，全面提升我们的物业服务能力，在生机勃勃的4月份，我们为业主带来了各种有趣的活动，增进小区的和谐氛围，提高业主的幸福度，敬请期待！</p><p style=\\\"text-align: right;\\\">2025.4.1</p><p style=\\\"text-align: right;\\\">物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-04-01 15:23:50\"},{\"aid\":8,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"关于失物领取相关公告\",\"content\":\"<p style=\\\"text-align: left;\\\">亲爱的业主：</p><p style=\\\"text-align: left;\\\"> &nbsp; &nbsp;最近有不少业主在小区内拾取到无人认领的失物，其中包括水杯，笔，雨伞等物品，请丢失相关物品的失主尽快到物业中心前台认领失物，也再次提醒各位业主注意随身物品，避免再次丢失导致个人利益损失，祝各位业主生活愉快！</p><p><br></p><p style=\\\"text-align: right;\\\">2025.3.14</p><p style=\\\"text-align: right;\\\">物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-14 15:46:36\"},{\"aid\":7,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"小区空调外机安全加固温馨提示\",\"content\":\"<p style=\\\"text-align: left;\\\">最近经物业人员巡查发现，<br><br>　　有个别业主家安装的空调外挂机不规范，存在诸多安全隐患。为了不影响您的正常生活，避免给您和他人带来不必要的损失，<br><br>　　请各位业主注意以下事项提示：<br><br>　　小区空调外机安全加固温馨提示<br><br>　　尊敬的业主：<br><br>　　您好!<br><br>　　近年来，由于常年风吹雨淋，小区部分空调室外机支架已出现松动、腐蚀等现象。空调室外机支架损坏导致维修工、室外机坠落的现象屡有发生，对行人及住户造成很大的安全隐患。请业主尽快做好以下几点防护措施，以保证自身和他人安全：<br><br>　　一、全体业主有安装空调外机的，检查空调外机支架是否存在歪斜、安装不牢固以及严重锈蚀等安全隐患。若发现安全隐患，请第一时间联系空调厂家进行安全检查以及加强外机的加固工作，防止因大风天气导致空调脱落，做到空调外机安装牢靠。<br><br>　　二、请勿将空调外机安装在除预留位置以外任何区域。严禁超出预留位置护栏安装。<br><br>　　三、及时检查空调室外机百叶窗、支架、护栏是否锈蚀、未关闭牢靠、松动、脱落等隐患，发现请及时维护或更换。<br><br>　　四、空调冷却水应引入室内或空调落水管排放，不得直接向沿建筑墙面和地面排放，不然使用空调时排水管长期滴水，日积月累会使墙面受损、腐蚀，同时滴答滴答的水声也会造成邻里不和谐。<br><br>　　五、不要在空调室外机、窗台上和窗户、阳台外等处搁置或悬挂物品。<br><br>　　六、检查空调主机排水软管是否有松脱、扭曲、压扁、破裂漏水，及时维护。<br><br>　　七、检查空调主机运行是否发出较大噪音，如有问题敬请业户联系专业空调维修单位进行维修保养。<br><br>　　八、空调外机及支架属产权人(业主)的自用部分，产权人(业主)有维护它的安全状态的义务和安全维护责任。<br><br>　　小区的平安、和谐，靠大家共同努力维护。感谢全体业主对小区的平安工作给予的积极支持和配合!<br><br>　　物业服务中心<br><br>　　2023年7月1日</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:21:44\"},{\"aid\":6,\"publisherId\":1,\"publisherName\":\"admin\",\"title\":\"物业公众号服务迁移的通知\",\"content\":\"<p style=\\\"text-align: left;\\\">关于物业公众号服务迁移的通知<br><br>　　尊敬的业主：<br><br>　　本公众号已更名为“南国丽城物业服务信息”，2019年11月1日起本公众号将停止所有服务。缴费、留言、报修、投诉建议等将全部迁移至新公众号“南国丽城物业服务中心”(微信号：XXXXX)。<br><br>　　请业主于2019年11月1日前关注新公众号，并在个人中心完成业主信息认证，以便及时接收物业信息、缴费通知，和使用各项功能，如：费用查询、费用缴纳、报修、投诉建议等。<br><br>　　嘉润物业将不断提高服务水平，为业主提供更优质、更便捷、更高效的物业服务。<br><br>　　新公众号(南国丽城物业服务中心)<br><br>　　二维码：(略)<br><br>　　罗定市嘉润物业服务有限公司<br><br>　　南国丽城物业服务中心</p>\",\"statusDesc\":\"已发布\",\"publishTime\":\"2025-03-03 20:21:04\"}]}}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:26:03');
INSERT INTO `system_log` VALUES (8896, 'GET', '{\"ARGS\":\"[1]\",\"CLASS_METHOD\":\"com.example.controller.RepairController.getByUid\",\"URL\":\"http://localhost:8080/api/repair/uid/1\",\"SPEND_TIME\":1,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:26:05');
INSERT INTO `system_log` VALUES (8897, 'GET', '{\"ARGS\":\"[repair]\",\"CLASS_METHOD\":\"com.example.controller.TypeController.allActive\",\"URL\":\"http://localhost:8080/api/type/all-active/repair\",\"SPEND_TIME\":2,\"RESPONSE\":{\"status\":200,\"success\":true,\"message\":[{\"tid\":15,\"type\":\"repair\",\"description\":\"电力维修\",\"status\":\"active\"},{\"tid\":16,\"type\":\"repair\",\"description\":\"水管维修\",\"status\":\"active\"},{\"tid\":17,\"type\":\"repair\",\"description\":\"电梯维修\",\"status\":\"active\"},{\"tid\":18,\"type\":\"repair\",\"description\":\"设备维修\",\"status\":\"active\"},{\"tid\":19,\"type\":\"repair\",\"description\":\"室内维修\",\"status\":\"active\"}]}}', NULL, '0:0:0:0:0:0:0:1', '2025-05-22 11:26:05');
